import 'package:geolocator/geolocator.dart';import 'package:get/get.dart';class GeoLocatorService extends GetxService {Future<GeoLocatorService> init() async {return this;}Future<Position> position() async {final bool serviceEnabled = await Geolocator.isLocationServiceEnabled();if (!serviceEnabled) {return Future.error('未開啟定位服務');}LocationPermission permission = await Geolocator.checkPermission();if (permission == LocationPermission.denied) {permission = await Geolocator.requestPermission();if (permission == LocationPermission.denied) {return Future.error('使用者未允許定位權限');}}if (permission == LocationPermission.deniedForever) {return Future.error('使用者未允許定位權限（永久），無法取得定位資訊');}return await Geolocator.getCurrentPosition();}}